{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C27"],
      "claim": "Alprazolam, a chlorinated fused heteroaromatic with a basic amine, has absolute oral bioavailability of 80–100% in humans, directly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Suvorexant, a chloro-substituted heteroaromatic drug, has 82% absolute oral bioavailability under fasted conditions in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Clobazam, a chlorinated benzodiazepine-like molecule, has 90–100% absolute oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "Ranitidine, despite variable absorption, has a measured mean absolute bioavailability of 0.60 ± 0.17 with a range of 0.35–0.79, all above the 20% threshold, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Maribavir, a halogenated heteroaromatic drug, has oral bioavailability of 30–40% in humans, the lowest quantitative value among key analogues but still above the 20% threshold, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues show human absolute oral bioavailability values well above 20%, mostly 46–100%, and the physicochemical prior is favorable; therefore the query is predicted to have high oral bioavailability at the F ≥ 20% threshold.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query molecule.",
    "Potential transporter-mediated efflux or first-pass metabolism specific to the query is not directly captured by the analogues.",
    "The query's strongly basic dimethylamino group may affect permeability, though moderate logD mitigates this concern."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

